self.KB_CONTENT["card:783115"]={"id":"card:783115","ty":"card","sourceId":"783115","title":"『應付票據交寄大宗郵件憑證』的作業重點有哪些？","ver":"GP4以上","topic":"憑證","keywords":["憑證","單身","應付","廠商"],"y":"explain","answer":"■作業重點1.本報表資料排序列印方式(1).廠商代號：依廠商代號排序印出。(2).票據號碼：依票據號碼排序印出。2.順序：自動編號 (流水號) 。3.每二十筆跳頁。4.件數=符合條件的單身總資料筆數。5.自訂憑證欄位：廠商全名欄位供自訂憑證使用。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
