self.KB_CONTENT["card:886401"]={"id":"card:886401","ty":"card","sourceId":"886401","title":"採購單建立作業EPMI35出現\"『預算控管序號:xxxx採購金額不可大於專案預算金額，請重新輸入!!』\"","ver":"AiGP 1.1.0以上","topic":"epmi","keywords":["epmi","採購單","單身","序號"],"y":"error","answer":"當『預算控管建立作業-EPMI15』的預算控管參數=\"S\"依金額控管，則採購單單身【採購金額】*【匯率】大於『預算控管建立作業-EPMI15』單身【預算-實際出貨差異額】，就會出現『預算控管序號:xxxx採購金額不可大於專案預算金額，請重新輸入!!』的訊息。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
