self.KB_CONTENT["field:847730"]={"id":"field:847730","ty":"field","sourceId":"847730","title":"人工提效率","ver":"GP40.iGP 以上","topic":"","keywords":[],"job":"專案預算彙總表列印作業","code":"","answer":"人工提效率(目標) = (目標預算金額-人工 - 實際成本-人工) / 目標預算金額-人工 目標預算金額-人工 = 品號類型(INV.MB9I2)='4'時, SUM(目標未稅預算金額(EPM.TB113))；實際金額-人工 = 品號類型(INV.MB9I2)='4'時, SUM(未稅實際金額(EPM.TB015))","file":"fields.jsonl"};
