self.KB_CONTENT["field:784129"]={"id":"field:784129","ty":"field","sourceId":"784129","title":"進貨單號","ver":"GP4以上","topic":"","keywords":[],"job":"資產進貨單建立作業","code":"TO002","answer":"* 不可空白。* 其單號編碼方式為「手動編號」須自行輸入不可空白，系統並檢查是否重覆，其餘自動預設單號。","file":"fields.jsonl"};
