self.KB_CONTENT["field:778012"]={"id":"field:778012","ty":"field","sourceId":"778012","title":"母製令單號","ver":"GP4以上","topic":"","keywords":[],"job":"製造命令變更建立作業","code":"TO026","answer":"* 不可空白。*『F2』可開窗查詢製令單別、製令單號、產品品號。","file":"fields.jsonl"};
self.KB_CONTENT["field:778117"]={"id":"field:778117","ty":"field","sourceId":"778117","title":"預計開工","ver":"GP4以上","topic":"","keywords":[],"job":"製造命令變更建立作業","code":"TO012","answer":"* 為此製令單之預定開工日。其欄位後緊跟著其對應之星期幾。* 開工日若為休假日則將星期的顏色將標示為紅色。* 自動預設預計開工-休假方式，亦可修改，點選(icon)或[F2]日期快手查詢，亦可空白。* 預計完工日不可小於預計開工日。","file":"fields.jsonl"};
self.KB_CONTENT["field:753301"]={"id":"field:753301","ty":"field","sourceId":"753301","title":"人員名稱","ver":"iGP","topic":"","keywords":[],"job":"製程代號建立作業","code":"CMS。MV002","answer":"* 此欄位僅作顯示。","file":"fields.jsonl"};
self.KB_CONTENT["field:778089"]={"id":"field:778089","ty":"field","sourceId":"778089","title":".輸入領料日期","ver":"GP4以上","topic":"","keywords":[],"job":"領料單自動產生作業","code":"","answer":"* 不可空白。* 預設系統日期。* 所輸入日期資料不可小於庫存現行年月且須大於帳務凍結日期。","file":"fields.jsonl"};
