self.KB_CONTENT["field:757770"]={"id":"field:757770","ty":"field","sourceId":"757770","title":"來源別","ver":"iGP","topic":"","keywords":[],"job":"請購變更建立作業","code":"TU010","answer":"* 此欄位僅作顯示。* 請購變更之來源別有1.MRP、2.LRP、3.再補貨建議表、4.BOM自動請購、5.訂單轉請購、6.製令需求檢視表及9.其他。","file":"fields.jsonl"};
